package com.sunrise.dentalclinic.bootstrap;
import com.sunrise.dentalclinic.model.*; import com.sunrise.dentalclinic.repository.UserRepository; import org.slf4j.*; import org.springframework.boot.CommandLineRunner; import org.springframework.core.env.Environment; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class AdminBootstrap implements CommandLineRunner {private static final Logger log=LoggerFactory.getLogger(AdminBootstrap.class);private final UserRepository repo;private final PasswordEncoder encoder;private final Environment env;public AdminBootstrap(UserRepository r,PasswordEncoder e,Environment v){repo=r;encoder=e;env=v;}
 @Override @Transactional public void run(String...args){String username=env.getProperty("APP_ADMIN_USERNAME"),password=env.getProperty("APP_ADMIN_PASSWORD");if(username==null||username.isBlank()||password==null||password.isBlank()){log.info("Initial administrator was not seeded because required environment variables are absent.");return;}if(repo.findByUsernameIgnoreCase(username).isPresent()){log.info("Initial administrator already exists; no changes made.");return;}var u=new User();u.setUsername(username.trim());u.setFullName("System Administrator");u.setPasswordHash(encoder.encode(password));u.setRole(Role.ADMIN);u.setEnabled(true);repo.save(u);log.info("Initial administrator account created successfully.");}}
